APPROVED_EDITS.setdefault('legal.html',[]).extend([('        <h2 id="affiliate">Affiliate Disclosure</h2>\n', '        <h2 id="payments">Payments &amp; the Bitcoin Household Plan</h2>\n        <p>The <a href="/tools/bitcoin-household-plan/">Bitcoin Household Plan</a> is free to build and costs $29 to print or export the binder.</p>\n        <ul>\n          <li><strong>Checkout:</strong> payment is handled by Lemon Squeezy, the merchant of record, at pymtw.lemonsqueezy.com. Lemon Squeezy collects your payment and billing details. <strong>PYMTW never sees your card number.</strong> Read Lemon Squeezy\'s <a href="https://www.lemonsqueezy.com/privacy" target="_blank" rel="noopener noreferrer">Privacy Policy</a> and <a href="https://www.lemonsqueezy.com/buyer-terms" target="_blank" rel="noopener noreferrer">Buyer Terms</a>.</li>\n          <li><strong>Your answers stay in your browser:</strong> the plan runs on your device, and your answers never leave it.</li>\n          <li><strong>License key check:</strong> after you buy, you enter a license key on the plan page. Only that key is sent to api.lemonsqueezy.com to check it.</li>\n          <li><strong>Stored on your device:</strong> the unlock is saved in your browser\'s localStorage. "Remove the key from this device" on the plan page clears it.</li>\n        </ul>\n\n        <h2 id="affiliate">Affiliate Disclosure</h2>\n')])

